    n_offsets = start_n + tl.arange(0, TILE_N)
    mask = n_offsets < N
    x1 = tl.load(in_ptr1 + pid * N + n_offsets, mask=mask, other=0.0).to(tl.float32)
    x2 = tl.load(in_ptr2 + pid * N + n_offsets, mask=mask, other=0.0).to(tl.float32)
