@libentry()
@triton.jit(do_not_specialize=["eps"])
def add_rms_norm_loop_persist_kernel(
    out_ptr,
    in_ptr1,
    in_ptr2,
    w_ptr,
    N,
    M,
    eps,
    TILE_N: tl.constexpr,
    NPROG: tl.constexpr,
):
    """Persistent variant of the two-pass loop kernel for N > 4096.

    Same per-row two-pass structure (pass 1: sum of squares over TILE_N
    chunks; pass 2: normalize in reverse chunk order), but a fixed
    ``NPROG``-program grid strides over the M rows instead of one CTA per
    row.  For (1024,65536) this removes the per-row-CTA dispatch share on
    top of a per-CTA workload that is large enough to overlap dispatch
    only partially (measured 2026-11-12: fp16 364.6 -> 340.3us, fp32
    600.0 -> 588.5us).
    """
    if tl.constexpr(in_ptr1.dtype.element_ty == tl.float16) or tl.constexpr(
        in_ptr1.dtype.element_ty == tl.bfloat16
    ):
        cdtype = tl.float32
    else:
        cdtype = in_ptr1.dtype.element_ty

    pid = tle.program_id(0)

    for row in tl.range(pid, M, NPROG):
        r1 = in_ptr1 + row * N
        r2 = in_ptr2 + row * N
        ry = out_ptr + row * N

        # Pass 1: compute sum(x^2) in chunks
        acc = tl.zeros((TILE_N,), dtype=tl.float32)
        num_steps = tl.cdiv(N, TILE_N)

        for step in range(0, num_steps - 1):
            n_offsets = step * TILE_N + tl.arange(0, TILE_N)
            x1 = tl.load(r1 + n_offsets).to(tl.float32)
            x2 = tl.load(r2 + n_offsets).to(tl.float32)
            x = x1 + x2
            acc += x * x

        # last step with mask
        start_n = (num_steps - 1) * TILE_N
        n_offsets = start_n + tl.arange(0, TILE_N)
        mask = n_offsets < N
        x1 = tl.load(r1 + n_offsets, mask=mask, other=0.0).to(tl.float32)
        x2 = tl.load(r2 + n_offsets, mask=mask, other=0.0).to(tl.float32)
        x = x1 + x2
        acc += x * x

        var = tl.sum(acc) / N
        rrms = 1 / tl.sqrt(var + eps)

        # Pass 2: normalize in reverse order (better L2 cache reuse)
        prev_multiple = prev_multiple_of(N, TILE_N)

        # first reverse step with mask
        n_offsets = prev_multiple + tl.arange(0, TILE_N)
        mask = n_offsets < N
        x1 = tl.load(
            r1 + n_offsets,
            mask=mask,
            other=0.0,
            eviction_policy="evict_first",
        ).to(cdtype)
        x2 = tl.load(
            r2 + n_offsets,
            mask=mask,
            other=0.0,
            eviction_policy="evict_first",
        ).to(cdtype)
        x = x1 + x2
        w = tl.load(w_ptr + n_offsets, mask=mask, other=0.0)
        y = (x * rrms * w).to(cdtype)
        tl.store(ry + n_offsets, y, mask=mask)

        for start_n in range(TILE_N, N, TILE_N):
            n_offsets = (prev_multiple - start_n) + tl.arange(0, TILE_N)
            x1 = tl.load(r1 + n_offsets, eviction_policy="evict_first").to(cdtype)
            x2 = tl.load(r2 + n_offsets, eviction_policy="evict_first").to(cdtype)
            x = x1 + x2
            w = tl.load(w_ptr + n_offsets)
            y = (x * rrms * w).to(cdtype)
            tl.store(ry + n_offsets, y)


# GCU row-batch dispatch constants (Libra/L600: 48 SPs, 448KB usable DSM per
# program at double-program residency, 896KB hard limit). Calibrated on the
# core bench shapes: the full add+rmsnorm pipeline wants at most ~32768
# lanes per program for fp16/bf16 (~6.5 B/elem) and ~16384 lanes for fp32
# (~16 B/elem); larger tiles lose the double-program residency and/or per-CTA
# byte rate. Fewer than ~32 programs under-fills the device, so the row
# factor is the largest power of two that keeps >= 32 programs within the
# lane budget. The launcher rejects grid.x > 65535.
_NUM_SPC = 48
_MIN_BATCH_BLOCKS = 32
_MAX_LANES_HALF = 32768
_MAX_LANES_FULL = 16384
_GRID_X_MAX = 65535
_ROW_BATCH_NUM_WARPS = 2

# Persistent dispatch (2026-11-12, calibrated on the core bench shapes).  A
# direct row-batch launch pays a ~103-160ns per-CTA dispatch cost that
# serializes against execution once the tile count exceeds the 48-way device
# concurrency (skip_layer_norm precedent), so tiles beyond 48 are strided
# over a fixed 48-program grid instead.  RTILE is additionally capped at 32
# rows in the persistent arm to stay inside the empirically-validated safe
# envelope of the 2D-tile broadcast-chain miscompile family (sibling
# fused_add_rms_norm persistent kernel).
_PERSIST_NUM_PROGRAMS = _NUM_SPC
_PERSIST_MAX_RTILE = 32
# Persistent two-pass loop kernel (N > 4096): TILE_N=8192 measured best on
# (1024,65536) for both fp16 (340.3 vs 350.3us at 16384) and fp32 (588.5 vs
# 618.5us at 4096); num_warps is perf-neutral in {2,4}.
_LOOP_PERSIST_TILE_N = 8192
_LOOP_PERSIST_NUM_WARPS = 4


def _row_batch_rtile(M, BLOCK_SIZE, itemsize):
    """Pick the row-batch factor for the single-tile kernel.

    Largest power-of-two ``RTILE`` that still spreads at least
    ``_MIN_BATCH_BLOCKS`` programs across the device, capped by the
    dtype-aware DSM lane budget. ``RTILE == 1`` keeps the legacy
    one-row-per-CTA kernel where batching would only drop parallelism.
    """
    if M <= _NUM_SPC:
        return 1
    max_lanes = _MAX_LANES_FULL if itemsize >= 4 else _MAX_LANES_HALF
    lanes_cap = max(1, max_lanes // BLOCK_SIZE)
    rtile = 1
    while rtile * 2 <= lanes_cap and triton.cdiv(M, rtile * 2) >= _MIN_BATCH_BLOCKS:
        rtile *= 2
    while rtile < lanes_cap and triton.cdiv(M, rtile) > _GRID_X_MAX:
        rtile *= 2
    return rtile


def add_rms_norm(x1, x2, normalized_shape, weight, eps=1e-5):
    """
    Add_RMSNorm: Add two inputs element-wise and apply RMS normalization.

    Args:
        x1: First input tensor
        x2: Second input tensor
        normalized_shape: Shape to normalize over (typically the last dimensions)
        weight: Optional weight tensor for the normalization
        eps: Epsilon value for numerical stability

    Returns:
        Normalized output tensor
    """
    logger.debug(
        "GEMS ADD_RMS_NORM FORWARD, [input1 shape]: %s, [input2 shape]: %s, [weight shape]: %s",
        x1.size(),
        x2.size(),
        weight.size() if weight is not None else None,
    )
    dim = x1.ndim - len(normalized_shape)
    M = math.prod(x1.shape[:dim])
    N = math.prod(normalized_shape)

    # Verify shapes match
    assert x1.shape == x2.shape, f"Input shapes must match: {x1.shape} vs {x2.shape}"

    x1 = x1.contiguous()
    x2 = x2.contiguous()
    weight = weight.contiguous()
    y = torch.empty_like(x1)

    with torch_device_fn.device(x1.device):
        if N <= 4096:
            BLOCK_SIZE = triton.next_power_of_2(N)
            RTILE = _row_batch_rtile(M, BLOCK_SIZE, x1.element_size())
            if RTILE == 1:
                add_rms_norm_kernel[M,](
                    y, x1, x2, weight, N, 1, N, 1, N, 1, N, eps, BLOCK_SIZE
                )
            elif triton.cdiv(M, RTILE) > _PERSIST_NUM_PROGRAMS:
                # More row tiles than the device runs concurrently: striding
                # a fixed 48-program grid over the tiles removes the per-CTA
                # dispatch cost (see add_rms_norm_persist_kernel).
                persist_rtile = min(RTILE, _PERSIST_MAX_RTILE)
                add_rms_norm_persist_kernel[_PERSIST_NUM_PROGRAMS,](
                    y,
                    x1,
                    x2,
                    weight,
                    N,
                    1,
                    N,
                    1,
                    N,
                    1,
                    M,
                    N,
                    triton.cdiv(M, persist_rtile),
                    eps,
                    BLOCK_SIZE,
                    persist_rtile,
                    _PERSIST_NUM_PROGRAMS,
                    M % persist_rtile == 0,
                    N == BLOCK_SIZE,
                    num_warps=_ROW_BATCH_NUM_WARPS,
                )
            else:
                blocks = triton.cdiv(M, RTILE)
                full_blocks = M // RTILE
                add_rms_norm_rowbatch_kernel[blocks,](
                    y,
                    x1,
                    x2,
                    weight,
                    N,
                    1,
                    N,
                    1,
                    N,
                    1,
                    M,
                    N,
                    full_blocks,
                    eps,
                    BLOCK_SIZE,
                    RTILE,
                    N == BLOCK_SIZE,
                    num_warps=_ROW_BATCH_NUM_WARPS,
                )
        elif M > _PERSIST_NUM_PROGRAMS:
            # Large-N two-pass shape with enough rows to fill the device:
            # persistent row-striding beats one-CTA-per-row dispatch.
            add_rms_norm_loop_persist_kernel[_PERSIST_NUM_PROGRAMS,](
                y,
                x1,
                x2,
                weight,
                N,
                M,
                eps,
                TILE_N=_LOOP_PERSIST_TILE_N,
                NPROG=_PERSIST_NUM_PROGRAMS,
                num_warps=_LOOP_PERSIST_NUM_WARPS,
            )
        else:
            add_rms_norm_loop_kernel[M,](y, x1, x2, weight, N, eps)

    return y
